#[test]
fn prec_calculator_divfloat_mulfloat_tighter_than_1_0_2_0_3_0() {
    mettail_runtime::clear_var_cache();
    {
        // Precedence test: DivFloat binds tighter than MulFloat
        let input_str = "1.0 * 2.0 / 3.0";
        let lang = CalculatorLanguage;
        let parsed = lang.parse_term(input_str).expect("parse should succeed");
        let report = mettail_testkit::runtime_report::run_ascent_oracle_report(
            &lang,
            parsed.as_ref(),
            "generated precedence eval",
        )
        .expect("eval should succeed");
        let outputs = mettail_testkit::runtime_report::report_observed_outputs(&report);
        assert!(
            mettail_testkit::runtime_report::report_contains_expected(
                &report,
                "0.6666666666666666"
            ),
            "{} should evaluate to 0.6666666666666666, got {:?}",
            input_str,
            outputs
        );
    }
}

